// ISS-2025-00820
function getPayload( frm ) {
    let deleted = frm.deletedPositions;

    return {
        timesheet_name: frm.doc.name,
        positions: ( deleted 
            ? frm.ts_positions.filter(( pos ) => !deleted.some( ( del ) => del == pos.name ) )
            : frm.ts_positions )
    };
}

async function checkLimits(frm) {
    const warnings = [];

    if (!frm.ts_positions || !frm.doc.name) return warnings;

    const payload = getPayload( frm );

    let result = await frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
    });

    if (result?.message) {
        result.message.forEach(r => {
           if (r.status == "block" || r.status == "warning") {
                warnings.push(r);
            } 
        });
    }

    return warnings;
}

function refresh_limits(frm) {
    if (!frm.ts_positions || !frm.doc.name) return;

    const payload = getPayload( frm );

    frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
        callback: ({ message }) => {
            if ( message) {
                apply_limit_styles(frm, message);
            }
        }
    });
}

function apply_limit_styles(frm, results) {
    results.forEach(r => {
        const btn = $(`#limits-${r.position }`);
        if (btn.length) {
            setButtonStyle(btn, r.status);
            let tooltip = ( r.planned_hours > 0 
                ? `${r.completion_percentage}% из ${r.planned_hours} ч.`
                : __("Planned work efforts are not defined") );
            btn.attr('title', tooltip);
        }
    });
}

//функция для стилей кнопок
function setButtonStyle(button, status) {
    const styles = {
        'block': { // Красный - превышена блокировка
            'color': '#f44336'
        },
        'message': { // Оранжевый - превышено уведомление
            'color': '#FF9800'
        },
        'warning': { // Желтый - превышено предупреждение
            'color': '#FFEB3B'
        },
        'normal': { // Зеленый - все в порядке
            'color': '#4CAF50'
        },
        'no-plan': { // Серый - нет плановых данных
            'color': '#9E9E9E'
        }
    };

    button.css(styles[status] || styles['no-data']);
}

// Функция для проверки плановых трудозатрат согласно настройки проекта ISS-2025-01298
function checkPlannedHoursAndLimits(frm) {
    return new Promise(async (resolve) => {
        const errors = [];
        const warnings = [];

        try {
            const positions = frm.ts_positions || [];

            if (!positions.length || !frm.doc.name) {
                return resolve({ errors, warnings });
            }

            // Упрощенный вызов - передаем только необходимые данные
            const planCheck = await frappe.call({
                method: 'project_workload_assignment.api.calculate_timesheet_limits',
                args: {
                    timesheet_name: frm.doc.name,
                    positions: positions.map(p => ({
                        name: p.name,
                        document_name: p.document_name,
                        project_role: p.project_role,
                        project: p.project,
                        status: p.status,
                        all_hours: p.all_hours
                        // Убрали передачу plan_required - теперь определяется на сервере
                    }))
                }
            });

            // Обработка результатов остается прежней
            (planCheck.message || []).forEach(r => {
                if (r.status === "block") {
                    if (r.planned_hours > 0) {
                        const max_hrs = r.limit * r.planned_hours / 100;
                        errors.push(
                            `Трудозатраты по задаче "${r.task_subject}" (роль: ${r.role}) ` +
                            `превысили блокирующий лимит (${max_hrs} ч.) ` +
                            `на ${r.total_hours - max_hrs} часа(ов).`
                        );
                    } else {
                        errors.push(
                            `Для задачи "${r.task_subject}" (роль: ${r.role}) ` +
                            `не определены обязательные плановые трудозатраты`
                        );
                    }
                } else if (r.status === "warning") {
                    warnings.push(r);
                }
            });
        } catch (error) {
            console.error('Error in checkPlannedHoursAndLimits:', error);
            errors.push('Ошибка при проверке плановых трудозатрат и лимитов');
        }

        resolve({ errors, warnings });
    });
}

function showTaskPlanFact(position, frm, buttonElement) {
    if (!position.document_name || position.document_name.trim() === '') {
        frappe.msgprint('Не выбрана задача для отображения информации');
        return;
    }

    let modal;
    const payload = getPayload(frm);

    frappe.call({
        method: 'project_workload_assignment.api.calculate_timesheet_limits',
        args: payload,
    }).then(results => {
        let result = results?.message.find((element) => element.position == position.name);

        modal = $(`
            <div class="modal fade" tabindex="-1" role="dialog" style="display: none;">
                <div class="modal-dialog" role="document" style="max-width: 650px;">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">${result.task_subject || position.document_name}</h5>
                            <button type="button" class="close" data-dismiss="modal" aria-label="Close">
                                <span aria-hidden="true">&times;</span>
                            </button>
                        </div>
                        <div class="modal-body">
                            ${result.planned_hours <= 0 && result.plan_required ? getNoPlanWarningHtml() : ''}
                            ${getCompletionTableHtml(result)}
                            ${getHoursNoteHtml(result)}
                            ${getCurrentUserHoursHtml(result, frm)}
                            ${getHoursUsers(result)}
                            ${getParentTaskInfoHtml(result)}
                        </div>
                        <div class="modal-footer">
                            <button type="button" class="btn btn-default btn-sm" data-dismiss="modal">Закрыть</button>
                        </div>
                    </div>
                </div>
            </div>
        `).appendTo('body');

        modal.on('click', 'a[data-task-link]', function(e) {
            e.preventDefault();
            const taskName = $(this).data('taskName');
            modal.modal('hide');
            frappe.set_route('Form', 'Task', taskName);
        });

        modal.modal('show');

        modal.on('hidden.bs.modal', function() {
            modal.remove();
        });
    });
}

function getNoPlanWarningHtml() {
    return `
        <div class="alert alert-danger" style="margin-bottom: 15px;">
            <i class="fa fa-exclamation-triangle"></i>
            <strong> Внимание!</strong> Для этой задачи обязательно указание плановых трудозатрат!
        </div>
    `;
}

function getCompletionTableHtml(result) {
    const calculatePercentage = (value) => {
        return result.planned_hours > 0 ? Math.round((value / result.planned_hours) * 100) : 0;
    };

    let rows = [];
    for (var key in result.hours_data) {
        if ( key != "users" && key != "user_hours" ) {
            rows.push({
                status: key == "total" ? __("Total") : key,
                isTotal: key == "total",
                plan: Number.parseFloat( result.planned_hours).toFixed( 1 ) ,
                fact: Number.parseFloat( result.hours_data[ key ] ).toFixed( 1 ) + ' ч.',
                percent: calculatePercentage( result.hours_data[ key ] )
            });
        }
    }

    return `
        <div class="frappe-table-container" style="margin-bottom: 15px;">
            <table class="table table-bordered" style="width: 100%; margin-bottom: 10px;">
                <thead>
                    <tr>
                        <th style="width: 30%;">Статус</th>
                        <th style="width: 20%; text-align: right;">План</th>
                        <th style="width: 20%; text-align: right;">Факт</th>
                        <th style="width: 30%;">% выполнения</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.map(row => `
                        <tr ${row.isTotal ? 'style="font-weight: bold;"' : ''}>
                            <td>${row.status}</td>
                            <td style="text-align: right;">${row.plan}</td>
                            <td style="text-align: right;">${row.fact}</td>
                            <td>
                                <div class="progress" style="height: 20px; margin-bottom: 0; ${row.percent > 100 ? 'position: relative;' : ''}">
                                    <div class="progress-bar ${row.percent > 100 ? 'progress-bar-danger' : 'progress-bar-success'}" 
                                         role="progressbar" 
                                         style="width: ${Math.min(row.percent, 100)}%;">
                                        ${row.percent <= 100 ? row.percent + '%' : ''}
                                    </div>
                                    ${row.percent > 100 ? 
                                        `<div class="progress-bar progress-bar-danger" 
                                              role="progressbar"
                                              style="width: ${row.percent - 100}%;">
                                         </div>
                                         <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-weight: bold; color: white;">
                                            ${row.percent}%
                                         </div>` : ''}
                                </div>
                            </td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
    `;
}

function getCurrentUserHoursHtml(result, frm) {
    const ownerFullName = frm.doc.timesheet_from_name;
    if (!ownerFullName) return '';

    const userHours = result.hours_data.user_hours || {};
    const ownerHoursByStatus = userHours[ownerFullName] || {};

    let totalOwnerHours = 0;
    for (const status in ownerHoursByStatus) {
        if (!Object.prototype.hasOwnProperty.call(ownerHoursByStatus, status)) continue;
        if (typeof ownerHoursByStatus[status] !== 'number') continue;
        totalOwnerHours += ownerHoursByStatus[status];
    }
    if (totalOwnerHours === 0) return '';

    const percentage = result.planned_hours > 0
        ? Math.round((totalOwnerHours / result.planned_hours) * 100)
        : 0;

    let statusBreakdown = '';
    const statuses = Object.keys(ownerHoursByStatus);
    if (statuses.length > 1) {
        statusBreakdown = `<br><small style="color: #6c757d;">`;
        statusBreakdown += statuses.map(status =>
            `${status}: ${ownerHoursByStatus[status].toFixed(2)} ч.`
        ).join(' | ');
        statusBreakdown += `</small>`;
    } else if (statuses.length === 1) {
        statusBreakdown = `<br><small style="color: #6c757d;">Статус: ${statuses[0]}</small>`;
    }

    return `
        <div style="margin: 15px 0; padding: 8px 10px; background-color: #f0f7ff; border-radius: 4px; border-left: 4px solid #007bff;">
            <strong>👤 ${ownerFullName}:</strong>
            <span style="font-size: 16px; font-weight: bold; color: #007bff;">${totalOwnerHours.toFixed(2)} ч.</span>
            ${result.planned_hours > 0 ? `
                <span style="color: #6c757d;"> (${percentage}% от плана)</span>
            ` : ''}
            ${statusBreakdown}
        </div>
    `;
}

function getHoursUsers(result) {
    let users = result.hours_data.users || [];
    users.push( cur_frm.doc.timesheet_from_name );
    users = [...new Set( users )].filter(( user ) => user && user != "" );
    if ( users ) {
        return `<br>Учтены часы от: ` + frappe.utils.comma_and( users );
    }
}

function getHoursNoteHtml(result) {
    if (result.used_children_for_actual ) {
        return `Фактические данные: с учетом других дочерних задач (${result.child_tasks_count} шт.)`;
    } else {
        return `Фактические данные: только текущая задача`;
    }
}

function getParentTaskInfoHtml(result) {
    if (result.planned_hours > 0) {
        let html = `
            <div class="hours-note">
                Плановые данные определены на уровне: ${result.plan_task_subject}
            </div>`;

        if (result.plan_sources && result.plan_sources.length > 0) {
            html += `<div class="hours-note">
                Источники плана:
                <ul>`;
            result.plan_sources.forEach(source => {
                html += `<li>${source.subject} (${source.task_name}): ${source.planned_hours} ч.</li>`;
            });
            html += `</ul></div>`;
        }

        return html;
    }
    return "";
}

