frappe.ui.form.on('Task', {
    refresh: function(frm) {
        var current_user = frappe.session.user;
        // Запрос на получение объектов User Timesheet
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "User Timesheet",
                filters: {
                    timesheet_from: current_user,
                    ut_status: ["in", ["Draft", "Rejected", "Rework"]],
                    ts_date_of_dispatch: ["<", frappe.datetime.nowdate()]
                },
                fields: ["name"]
            },
            callback: function(response) {
                if (response.message && response.message.length > 0) {
                    // Извлекаем имена таймшитов
                    var timesheet_names = response.message.map(function(ts) { return ts.name; });
                    let past = localStorage.getItem( frappe.user.name + ":ts-overdue" )

                    if ( !past || ( new Date() - new Date( past ) ) > 3600 * 0.5 * 1000 ) {
                        console.log("Прошло полчаса - напоминаем про просроченные ТШ..");
                        // Если есть просроченные таймшиты, выводим сообщение с кнопкой
                        frappe.msgprint({
                            title: __('Просроченные Таймшиты'),
                            message: __('У вас есть просроченные Таймшиты. Срочно заполните их и отправьте на согласование!'),
                            primary_action: {
                                'label': __('Перейти к Таймшитам'),
                                'action': function() {
                                    cur_dialog.clear();
                                    // Устанавливаем параметры маршрута
                                    frappe.route_options = {
                                        name: ["in", timesheet_names]
                    
                                    };
    
                                    // Переход к списку User Timesheet
                                    frappe.set_route('List', 'User Timesheet');
                                }
                            },
                            secondary_action: {
                                'label': __('Напомнить позже'),
                                'action': function() {
                                    // Закрытие уведомление
                                    localStorage.setItem( frappe.user.name + ":ts-overdue", new Date() );
                                    cur_dialog.clear();
                                    cur_dialog.hide();
                                }
                            }
                        });
                    }
                }
            }
        });
    }
});

